args.new_string:
async function getDashboardData() {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch('http://localhost:3000/api/analytics').then(r => r.json()),
      fetch('http://localhost:3000/api/notifications').then(r => r.json()),
      fetch('http://localhost:3000/api/settings').then(r => r.json())
    ]);

    return { analytics, notifications, settings };
  } catch {
    // Return mock data for build time or error cases
    return {
      analytics: { 
        visits: 5000, 
        bounceRate: '45%', 
        activeUsers: 120 
      },
      notifications: [
        { id: 1, message: 'System update scheduled', type: 'info' },
        { id: 2, message: 'New user registration', type: 'success' }
      ],
      settings: { 
        theme: 'dark', 
        notificationsEnabled: true 
      }
    };
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData();

  return (
    <div className="p-4 space-y-6">
      <h2 className="text-2xl font-bold">Dashboard Content</h2>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="p-4 border rounded shadow-sm">
          <h3 className="font-semibold mb-2">Analytics</h3>
          <ul className="space-y-1">
            <li>Visits: {analytics.visits}</li>
            <li>Bounce Rate: {analytics.bounceRate}</li>
            <li>Active Users: {analytics.activeUsers}</li>
          </ul>
        </div>

        <div className="p-4 border rounded shadow-sm">
          <h3 className="font-semibold mb-2">Notifications</h3>
          <ul className="space-y-1">
            {notifications.map((n: any) => (
              <li key={n.id} className="text-sm">
                {n.message}
              </li>
            ))}
          </ul>
        </div>

        <div className="p-4 border rounded shadow-sm">
          <h3 className="font-semibold mb-2">Settings</h3>
          <ul className="space-y-1">
            <li>Theme: {settings.theme}</li>
            <li>Notifications: {settings.notificationsEnabled ? 'On' : 'Off'}</li>
          </ul>
        </div>
      </div>
    </div>
  );
}

